// Granola on an API key: every operation in Granola's public API (notes, transcripts, search, folders, spaces, analytics,
// audit log, legal holds, webhook endpoints). actions.json is generated by `bun scripts/openapi-actions.ts granola`;
// notes being written, edited or shared start automations by webhook (triggers.ts).
import type { OwnApp } from "../index";
import { type Api, call, specActions } from "../openapi";
import { events, receive, triggers, unwatch, wanted, watch } from "./triggers";

export const api: Api = {
  name: "Granola",
  base: "https://public-api.granola.ai",
  tokenHelp: "Granola desktop app → Settings → Connectors → API keys",
};

export const granola: OwnApp = {
  app: "granola",
  name: "Granola",
  logo: "/logos/granola.png",
  keyField: {
    label: "API key",
    help: "In the Granola desktop app: Settings → Connectors → API keys → Create new key, tick both Personal notes and Public notes, then Generate API Key and copy it (it starts with grn_). Needs a Granola Business or Enterprise plan; on Enterprise an admin may first have to allow API access (Settings → Workspace → General → Apps & connectors → API access). An admin can instead make a workspace key under Settings → Connectors → Workspace API keys, for the whole team's shared notes.",
    placeholder: "grn_...",
  },
  async check(key) {
    await call(api, key, { method: "GET", path: "/v1/notes", query: ["page_size"], headers: [] }, { page_size: 1 });
  },
  push: {
    events,
    triggers,
    start: (key, connection, event) => watch(api, key, connection, event),
    stop: (key, id) => unwatch(api, key, id),
    receive: (delivery, key) => receive(api, delivery, key),
    wanted,
  },
  actions: await specActions(new URL("./actions.json", import.meta.url), api),
};
